function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Start by painting the sky
  brush.fill("#7a5e4b");
  brush.fillBleed(0.7); // Use some bleeding to simulate depth
  brush.beginShape();
  brush.vertex(200, 200); // Position at the top of the hills
  brush.vertex(200, 150); // Position at the bottom of the hills
  brush.vertex(300, 100); // Position at the side of the hills
  brush.vertex(250, 200); // Final position of the hill
  brush.endShape(true);

  // Next, paint the hills
  brush.fill("#4f3838");
  brush.fillBleed(0.9);
  brush.vertex(150, 150); // Base of the hill
  brush.vertex(100, 250); // Side of the hill
  brush.vertex(175, 250); // Top of the hill
  brush.endShape(true);

  // Add some color to the water
  brush.fill("#87c389");
  brush.fillBleed(0.5);
  brush.circle(200, 200, 200); // Circle to represent the water
}
```

