function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Paint the sky using a solid color
  brush.fill("#87CEFA", 255);
  brush.circle(200, 200, 200);

  // Paint the hills as a rough texture
  brush.fill("#33A852", 255);
  brush.fillTexture(0.8, 0.6); // Create a blue hill texture
  brush.vertex(150, 250);
  brush.vertex(250, 250);
  brush.vertex(200, 300);
  brush.endShape(true);

  // Paint the cloud shapes using floating shapes
  brush.fill("#87CEFA", 255);
  brush.fillTexture(0.8, 0.8); // Add a light gray cloud texture
  brush.beginShape();
  brush.vertex(200, 150); // Smaller cloud
  brush.vertex(220, 160);
  brush.vertex(190, 170);
  brush.vertex(250, 200); // Larger cloud
  brush.endShape(true); 
}

