function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Add sun
  brush.fill("#ff9900", 100); // Sun color with full opacity
  brush.beginShape();
  brush.vertex(0, 100); // Top of the sun
  brush.vertex(0, 200); // Right side of the sun
  brush.vertex(400, 200); // Bottom of the sun
  brush.vertex(200, 400); // Left side of the sun
  brush.endShape(true);

  // Add hills
  brush.fill("#6a6833", 60); // Green hills
  brush.beginShape();
  brush.vertex(0, 300); // Top of the hills
  brush.vertex(400, 300); // Bottom of the hills
  brush.vertex(200, 500); // Left side of the hills
  brush.vertex(150, 350); // Bottom of the hills
  brush.endShape(true);

  // Add sun's rays
  brush.fill("#ff8c00", 80); // Sun's rays
  brush.beginShape();
  brush.vertex(200, 100); // Top of the rays
  brush.vertex(200, 300); // Right side of the rays
  brush.vertex(350, 250); // Bottom of the rays
  brush.vertex(350, 150); // Left side of the rays
  brush.endShape(true);

  // Add sky
  brush.fill("#c4c6ad", 15); // Sky color
  brush.beginShape();
  brush.vertex(0, 0); // Top left of the sky
  brush.vertex(400, 0); // Top right of the sky
  brush.vertex(400, 400); // Bottom right of the sky
  brush.vertex(0, 400); // Bottom left of the sky
  brush.endShape(true);
}
