function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // South: dark green hills

  brush.fill("#009240", 140);  // Maybe change opacity to see if it's valid

  brush.endShape(true);

  // South, east: soften hills

  brush.fill("#2b762a", 60);
  brush.fillBleed(0.4);

  brush.vertex(120, 60);  // soften hill

  // South, east: widen hill

  brush.fill("#8d879b", 60);
  brush.fillBleed(0.6);

  brush.vertex(140, 60);

  brush.vertex(100, 90);

  // South: nearby hill

  brush.fill("#c0b36b", 80);  // Sky

  brush.beginShape(curvature);

  brush.vertex(300, 320);  // hill on the right, near south
  brush.vertex(270, 280);  // hill on the left, near south

  brush.endShape(true);

  // Sky in the north

  brush.fill("#6a924c", 60);
  brush.fillBleed(1);  // Simulate that smoke pushes ever so slightly

  brush.vertex(0, 400);

  brush.vertex(200, 0);
  brush.vertex(0, 200);  // Create a clear horizon

  brush.vertex(400, 0);  // Drive the furthest horizon to the right

  brush.endShape(true);

  // Use a blob to paint away the water

  brush.fill("#525555", 10);
  brush.fillBleed(1);

  brush.vertex(200, 300);
  brush.vertex(300, 340);

  brush.endShape(true);

  // Paint the remaining parts of the hill (a strip) that lies below the blob

  brush.fill("#a08c6b", 80);  // Wait, is this a good color combination?
  brush.vertex(100, 290);  

  // Final touches to paint more gradient color

  brush.vertex(300, 295);
  brush.vertex(200, 320);

  brush.endShape(true);
}
