  brush.circle(x, y, hillRadius - 50); // Hill with a slight light color inside

  // Overlap of hill color
  brush.fill('#b86e3c', 90); // 'b86e3c' is a dark green color
  brush.vertex(250 + 10, 100); // Vertex to create a feeling of sun
  brush.vertex(200, 50); // Vertex for the horizon

