function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // First layer: the green hills
  brush.fill("#87cefa"); // Sky color
  brush.circle(200, 200, 50); // Draw a hill

  // Second layer: the sun
  brush.fill("#f7c145");
  brush.fillBleed(0.5); // Adjust bleed for a soft sun
  brush.vertex(100, 150); // Starting point for the sun
  brush.vertex(150, 100); // Draw the sun's face
  brush.endShape(true);

  // Third layer: the mist
  brush.fill("#4b6c7f");
  brush.vertex(120, 120); // Starting point for the mist
  brush.vertex(140, 140); // Draw the mist
  brush.endShape(true);

  // Fourth layer: the horizon
  brush.fill("#c2c2c2");
  brush.vertex(200, 250); // Starting point for the horizon
  brush.vertex(300, 275); // Draw the horizon
  brush.endShape(true);

  // Fifth layer: The sun's rays
  brush.fill("#f9f9ff");
  brush.vertex(300, 200); // Starting point for the rays
  brush.vertex(320, 180); // Draw the rays
  brush.endShape(true);

  // Additional details and sun outlines
  brush.fill("#1e90ff");
  brush.vertex(310, 190); // Add sun outline
}
