function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Create the sky
  brush.fill("#a6d8c3");
  brush.beginShape();
  brush.vertex(400, 400); // Leftmost point
  brush.vertex(0, 400); // Rightmost point
  brush.vertex(200, 200); // Center point
  brush.endShape(true);

  // Create the hills
  brush.fill("#76a58f"); // Green color for hills
  brush.beginShape();
  brush.vertex(200, 300); // Leftmost hill
  brush.vertex(400, 250); // Rightmost hill
  brush.vertex(200, 200); // Center of the hill
  brush.endShape(true);

  // Create the sun
  brush.fill("#f99912"); // Yellow color for the sun
  brush.beginShape();
  brush.vertex(300, 50); // Leftmost point of the sun
  brush.vertex(200, 200); // Center point of the sun
  brush.vertex(200, 100); // Rightmost point of the sun
  brush.endShape(true);

  // Create the shadows
  brush.fill("#8e350b"); // Dark yellow color for shadows
  brush.beginShape();
  brush.vertex(200, 150); // Leftmost shadow
  brush.vertex(300, 150); // Rightmost shadow
  brush.vertex(200, 100); // Center shadow
  brush.endShape(true);
}
